// returns the push for both motors together as a fraction of 2 x torque_limit, in [-1, 1]
inline float standup_policy(const float* o) {
  using namespace standup_nn;
  float h0[64], h1[64];
  for (int j = 0; j < 64; ++j) { float s = B0[j]; for (int i = 0; i < 6; ++i) s += W0[j * 6 + i] * o[i]; h0[j] = std::tanh(s); }
  for (int j = 0; j < 64; ++j) { float s = B1[j]; for (int i = 0; i < 64; ++i) s += W1[j * 64 + i] * h0[i]; h1[j] = std::tanh(s); }
  float y = B2[0]; for (int i = 0; i < 64; ++i) y += W2[i] * h1[i];
  return y > 1.f ? 1.f : (y < -1.f ? -1.f : y);
}
